#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
const int MAXN = 100001;

#define int long long

int x, y, n;
double best_diff = 1e9;
int best_num, best_den;

int compute_lcm(int a, int b) {
    return a * b / __gcd(a, b);
}

int main() {
    cin >> x >> y >> n;
    if (y <= n) {
        while (__gcd(x, y) > 1) {
            int g = __gcd(x, y);
            x /= g;
            y /= g;
        }
        cout << x << "/" << y;
        return 0;
    }
    for (int i = 1; i <= n; i++) {
        int h = compute_lcm(i, y);
        int w = x * (h / y);
        double diff1 = (double)(w - ((w / (h / i)) * (h / i))) / (double)h;
        if (best_diff > diff1) {
            best_diff = diff1;
            best_num = (w / (h / i));
            best_den = i;
        }
        int numerator = w + (h / i) - 1;
        int denominator = (h / i);
        double diff2 = (double)abs(w - (((numerator) / denominator) * denominator)) / (double)h;
        if (best_diff > diff2) {
            best_diff = diff2;
            best_num = ((numerator) / denominator);
            best_den = i;
        }
    }
    int g = __gcd(best_num, best_den);
    best_num /= g;
    best_den /= g;
    cout << best_num << "/" << best_den;
}
